/**
 * The top level domain check against the IANA root zone: a domain whose
 * last label is not one IANA publishes (`acme.con`, `mail.local`, a bare
 * `localhost`) can never resolve on the public internet, so mail to it
 * never arrives. The list is `data/tlds.ts`, regenerated by
 * `scripts/update-tlds.mjs`. Pure, no I/O.
 */

import { IANA_TLD_LIST } from '../data/tlds.js'

/**
 * Every top level label IANA publishes, lowercase, ASCII and punycode
 * (`xn--p1ai` for `.рф`).
 */
export const IANA_TLDS: ReadonlySet<string> = new Set(
  IANA_TLD_LIST.split('\n').filter((line) => line.length > 0)
)

/**
 * The rightmost dotted label of a host name, lowercased. Null for a name
 * without a dot (`localhost`, `intranet`), which is never public.
 * @param hostname - A host name, ASCII (punycode) form
 * @returns The top level label, or null
 */
function extractTld(hostname: string): string | null {
  const lower = hostname.toLowerCase().trim()
  // A root anchored name (`example.com.`) loses its trailing dot.
  const stripped = lower.endsWith('.') ? lower.slice(0, -1) : lower
  const lastDot = stripped.lastIndexOf('.')
  if (lastDot <= 0 || lastDot === stripped.length - 1) {
    return null
  }
  return stripped.slice(lastDot + 1)
}

/**
 * Whether a host name ends in a TLD IANA publishes. ASCII and punycode
 * (`xn--...`) labels are accepted; convert a native script name to
 * punycode first (`toAsciiDomain` does that, and `isKnownTld` calls it).
 *
 * - `hasValidTld('example.com')` is true
 * - `hasValidTld('a.b.example.co.uk')` is true (`.uk`)
 * - `hasValidTld('11111rs-access323.del')` is false (no `.del`)
 * - `hasValidTld('localhost')` is false (no TLD)
 * - `hasValidTld('xn--80ahbyjlf.xn--p1ai')` is true (Cyrillic IDN)
 * @param hostname - A lowercased host name (`URL.hostname` output is fine)
 * @returns True when the TLD exists in the DNS root zone
 */
export function hasValidTld(hostname: string): boolean {
  const tld = extractTld(hostname)
  return tld !== null && IANA_TLDS.has(tld)
}
